using namespace P4MapKit::Material;
int checks=0;void Check(bool ok,const char* text){++checks;if(!ok)throw std::runtime_error(text);}template<class F>void Refuses(F f,const char* category){++checks;try{f();}catch(const Refused& e){if(e.name==category)return;throw;}throw std::runtime_error("expected source plan refusal");}
int main(){try{MaterialPreparedProgram prepared;prepared.Reference.Frequency=3;prepared.Reference.VertexFactoryHash=0xdd651790dd308138ull;prepared.BaseBinding.Varyings["in_texcoord6"]=23;prepared.Lines={"STORAGE sbo_buf0[] = { program.storage[0] }","MOV.F R0.xy, fragment.attrib[23]","MOV.F R0.z, {0}.x","MAX.F result_color0.xyz, R0, {0}.x","MOV.F result_color0.w, {0}.x"};const auto settings=Object({{"domain","MD_Surface"},{"shading_model","MSM_Unlit"},{"blend_mode","BLEND_Opaque"},{"two_sided",false},{"clip",0.3333}});int callbacks=0;const auto sourcePlan=PlanOriginalMaterialPixelRecovery(prepared,settings,Json::MakeObject(),[&](SymbolicArena&,BindingContext& context){++callbacks;Check(context.Interpolants.count("in_texcoord6"),"factory contract is installed before engine callback");});Check(sourcePlan.Factory=="TGPUSkinMorphVertexFactoryDefault"&&sourcePlan.FactoryContractInstalled,"source exact factory association");Check(sourcePlan.OriginalLines==std::vector<std::size_t>{1,2,3,4}&&sourcePlan.StorageDeclarations.size()==1,"source original line evidence preserved");const auto graph=RecoverUnlitMaterialExpressionGraph(sourcePlan.Recovery);Check(callbacks==1&&!graph.FamilyComplete&&!graph.CompilerProven,"source plan executes callback once without inventing proof");bool uv=false;for(const auto& n:graph.Graph.At("nodes").object)if(n.second.At("type").Text()=="TextureCoordinate"&&n.second.At("props").At("CoordinateIndex").Numeric()==6)uv=true;Check(uv,"prepared skin source produces UV6 graph");auto wrongFrequency=prepared;wrongFrequency.Reference.Frequency=0;Refuses([&]{PlanOriginalMaterialPixelRecovery(wrongFrequency,settings);},"material source pixel frequency");auto unknown=prepared;unknown.Reference.VertexFactoryHash=1;Refuses([&]{PlanOriginalMaterialPixelRecovery(unknown,settings);},"material vertex factory inputs");auto ui=settings;ui["domain"]="MD_UI";Check(PlanOriginalMaterialPixelRecovery(prepared,ui).FactoryContractInstalled,"UI mesh source installs its authoritative factory");auto post=settings;post["domain"]="MD_PostProcess";Refuses([&]{PlanOriginalMaterialPixelRecovery(prepared,post);},"material source postprocess inputs");auto global=prepared;global.Reference.VertexFactoryHash=0;global.BaseBinding.Varyings.clear();const auto postPlan=PlanOriginalMaterialPixelRecovery(global,post);Check(!postPlan.FactoryContractInstalled&&postPlan.Factory.empty(),"global postprocess does not inherit mesh tables");auto light=post;light["domain"]="MD_LightFunction";Check(!PlanOriginalMaterialPixelRecovery(global,light).FactoryContractInstalled,"light function source uses no guessed mesh factory");Refuses([&]{PlanOriginalMaterialPixelRecovery(prepared,light);},"material source global inputs");auto decal=post;decal["domain"]="MD_DeferredDecal";Check(PlanOriginalMaterialPixelRecovery(prepared,decal).FactoryContractInstalled&&!PlanOriginalMaterialPixelRecovery(global,decal).FactoryContractInstalled,"decal separates authoritative mesh and global scopes");std::cout<<"native source plan checks="<<checks<<"\n";}catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}return 0;}
